+    public static void main(String[] args) {
+        assertIndex("finds middle value", new int[] { 2, 3, 4, 10, 40 }, 10, 3);
+        assertIndex("finds first value", new int[] { 2, 3, 4, 10, 40 }, 2, 0);
+        assertIndex("finds last value", new int[] { 2, 3, 4, 10, 40 }, 40, 4);
